// Aetherus Remote Observatory safe-hold contract. This is not a hardware driver.
// It deliberately cannot issue network/device commands; every unsafe or stale input remains HOLD.
export const REMOTE_OBSERVATORY_SCHEMAS = Object.freeze({ authorization: 'earthus.remote-observatory-authorization.v1', decision: 'earthus.remote-observatory-decision.v1' });
export class RemoteObservatoryError extends Error { constructor(code) { super(code); this.name = 'RemoteObservatoryError'; this.code = code; } }
const fail = code => { throw new RemoteObservatoryError(code); }; const need = (v, c) => { if (!v) fail(c); }; const freeze = v => { if (v && typeof v === 'object' && !Object.isFrozen(v)) { Object.values(v).forEach(freeze); Object.freeze(v); } return v; };
const utc = value => { const d = new Date(value); need(Number.isFinite(d.getTime()), 'REMOTE_UTC_REQUIRED'); return d.toISOString(); };
const token = (value, code) => { const result = String(value || '').trim(); need(/^[A-Za-z0-9._:-]+$/.test(result), code); return result; };
export function issueSingleUseAuthorization({ authorizationId, issuedAtUtc, expiresAtUtc, requestedAction, userConfirmed } = {}) { need(userConfirmed === true, 'REMOTE_USER_CONFIRMATION_REQUIRED'); need(requestedAction === 'SAFE_CAPTURE_SEQUENCE', 'REMOTE_ACTION_NOT_ALLOWED'); const issued = Date.parse(utc(issuedAtUtc)); const expires = Date.parse(utc(expiresAtUtc)); need(expires > issued && expires - issued <= 5 * 60 * 1000, 'REMOTE_AUTHORIZATION_WINDOW_INVALID'); return freeze({ schema: REMOTE_OBSERVATORY_SCHEMAS.authorization, authorizationId: token(authorizationId, 'REMOTE_AUTHORIZATION_ID_REQUIRED'), requestedAction, issuedAtUtc: new Date(issued).toISOString(), expiresAtUtc: new Date(expires).toISOString(), singleUse: true, consumed: false }); }
export function evaluateRemoteSafeHold({ authorization, nowUtc, weather, dome, mount, emergencyStop = false } = {}) { const now = Date.parse(utc(nowUtc)); const reasons = []; if (emergencyStop) reasons.push('EMERGENCY_STOP_ACTIVE'); if (!authorization || authorization.schema !== REMOTE_OBSERVATORY_SCHEMAS.authorization || authorization.consumed) reasons.push('AUTHORIZATION_MISSING_OR_USED'); else if (now > Date.parse(authorization.expiresAtUtc)) reasons.push('AUTHORIZATION_EXPIRED'); if (!weather || !weather.observedAtUtc || now - Date.parse(weather.observedAtUtc) > 10 * 60 * 1000) reasons.push('WEATHER_STALE'); if (weather?.safe !== true) reasons.push('WEATHER_NOT_SAFE'); if (dome?.state !== 'OPEN' || dome?.observedAtUtc === undefined || now - Date.parse(dome.observedAtUtc) > 60 * 1000) reasons.push('DOME_NOT_OPEN_OR_STALE'); if (mount?.state !== 'TRACKING' || mount?.observedAtUtc === undefined || now - Date.parse(mount.observedAtUtc) > 60 * 1000) reasons.push('MOUNT_NOT_TRACKING_OR_STALE'); if (dome?.targetId && mount?.targetId && dome.targetId !== mount.targetId) reasons.push('DOME_MOUNT_TARGET_MISMATCH'); return freeze({ schema: REMOTE_OBSERVATORY_SCHEMAS.decision, state: reasons.length ? 'SAFE_HOLD' : 'AUTHORIZED_NO_DRIVER', reasons, deviceCommand: null, cloudBypass: false, evaluatedAtUtc: new Date(now).toISOString() }); }
export function consumeRemoteAuthorization(authorization, decision) { need(decision?.state === 'AUTHORIZED_NO_DRIVER', 'REMOTE_DECISION_NOT_AUTHORIZED'); need(authorization?.consumed === false, 'REMOTE_AUTHORIZATION_ALREADY_USED'); return freeze({ ...authorization, consumed: true, consumedAtUtc: decision.evaluatedAtUtc }); }
